              "content": "//position of LEDs in the Arduino\nint led_yellow = 8;\nint led_red = 9;\n\n//unsigned : only 0 and (+ve) values\n//long : more space in the memory\n//fixing intervals for both LEDs \nunsigned long interval_yellow = 1000;\nunsigned long interval_red = 2000;\n\n//Last time when LEDs were off\nunsigned long lastTime_yellow = 0;\nunsigned long lastTime_red = 0;\n\n//Initial state, which is off\nint state_yellow = LOW;\nint state_red = LOW;\n\n//Preparing 8 and 9 pins for output, means arduino will send command outside (to LEDs)\nvoid setup(){\n  pinMode(led_yellow, OUTPUT);\n  pinMode(led_red,OUTPUT);\n}\n\n//To work in loops with intervals for both LEDs\nvoid loop(){\n  unsigned long currentTime = millis(); /* millis : Asks 'after how much time';\n  setting time for different values, can work independtly which 'delay' can't.*/\n\n  if (currentTime - lastTime_yellow >= interval_yellow) {\n    lastTime_yellow = currentTime;\n    if (state_yellow == LOW) {\n      state_yellow = HIGH;\n    } else {\n      state_yellow = LOW;\n    }\n    digitalWrite (led_yellow, state_yellow);\n  }\n\n  if (currentTime - lastTime_red >= interval_red) {\n    lastTime_red = currentTime;\n    if (state_red == LOW) {\n      state_red = HIGH;\n    } else {\n      state_red = LOW;\n    }\n    digitalWrite(led_red, state_red);\n  }\n}"
