              "content": "int ledPin = 9; // LED connected to digital pin 9\n\n// value: Brightness level (0 to 255)\nvoid pwm(int pin, int value) {\n  // Setting value within 0 - 255 range\n  if (value < 0) value = 0;\n  if (value > 255) value = 255;\n\n  // Total time = 10,000 microseconds\n  int time = 10000; \n\n  int onTime = (time * value) / 255; //Duty cycle for onTime \n  int offTime = time - onTime;\n\n  // Execute ON phase\n  if (onTime > 0) {\n    digitalWrite(pin, HIGH);\n    delayMicroseconds(onTime); \n  }\n\n  // Execute OFF phase\n  if (offTime > 0) {\n    digitalWrite(pin, LOW);\n    delayMicroseconds(offTime);\n  }\n}\n\nvoid setup() {\n  pinMode(ledPin, OUTPUT);\n}\n\nvoid loop() {\n  // Gradually increase brightness (Fade In)\n  // This condition for increasing brightness with time\n  for (int brightness = 0; brightness <= 255; brightness += 5) {\n    // Time gap \n    for (int i = 0; i < 10; i++) {\n      pwm(ledPin, brightness);\n    }\n  }\n\n  // Gradually decrease brightness (Fade Out)\n  for (int brightness = 255; brightness >= 0; brightness -= 5) {\n    for (int i = 0; i < 10; i++) {\n      pwm(ledPin, brightness);\n    }\n  }\n}"
